mapper.select:
SELECT o.id, o.order_no, o.warehouse_id, w.name AS warehouse_name, o.location_id, o.location_code, o.location_name, o.status, o.total_items, o.counted_items, o.diff_items, o.gain_qty, o.loss_qty, o.remark, o.post_time, o.create_time, o.update_time FROM stocktaking_order o LEFT JOIN warehouse w ON w.id = o.warehouse_id AND w.deleted = 0 WHERE o.deleted = 0
AND (o.order_no LIKE CONCAT('%', #{query.keyword}, '%') OR o.location_code LIKE CONCAT('%', #{query.keyword}, '%') OR o.location_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND o.warehouse_id = #{query.warehouseId}
AND o.location_id = #{query.locationId}
AND o.status = #{query.status}
AND o.create_time >= #{query.beginTime}
AND o.create_time < DATE_ADD(#{query.endTime}, INTERVAL 1 DAY)
ORDER BY FIELD(o.status, 'COUNTING', 'COMPLETED', 'CANCELLED') ASC, o.id DESC

mapper.update:
UPDATE stocktaking_order
SET status    = 'CANCELLED',
    update_by = #{updateBy}
WHERE id = #{id}
  AND status = 'COUNTING'
  AND deleted = 0
